-- 確認用
SELECT
  (SELECT count(*) FROM general_questions WHERE council_session_id = (SELECT id FROM council_sessions WHERE slug = 'r8-4-teireikai')) AS questions,
  (SELECT count(*) FROM general_question_items i JOIN general_questions q ON q.id = i.question_id WHERE q.council_session_id = (SELECT id FROM council_sessions WHERE slug = 'r8-4-teireikai') AND i.parent_id IS NULL) AS titles,
  (SELECT count(*) FROM general_question_items i JOIN general_questions q ON q.id = i.question_id WHERE q.council_session_id = (SELECT id FROM council_sessions WHERE slug = 'r8-4-teireikai') AND i.parent_id IS NOT NULL) AS subs;
